<script setup>
import VendorLayout from '../../../Layouts/VendorLayout.vue';
import { Link, router } from '@inertiajs/vue3';
import { computed } from 'vue';
import { appUrl } from '../../../appUrl';

const props = defineProps({ properties: Array, propertyId: Number, dashboard: Object });
const date = computed(() => props.dashboard.date);
const tomorrow = computed(() => { const value = new Date(`${date.value}T00:00:00`); value.setDate(value.getDate() + 1); return value.toISOString().slice(0, 10); });
function select(event) { router.get(appUrl('/vendor/hotel/operations'), { property_id: event.target.value || undefined, date: date.value }, { preserveState: true }); }
function changeStatus(row, status) { router.patch(row.status_url, { status }, { preserveScroll: true }); }
</script>
<template><VendorLayout><div class="container-fluid py-3">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h1 class="h3 mb-1">Hotel Operations</h1><p class="text-muted mb-0">Arrivals, departures and room availability for {{ date }}.</p></div><div class="d-flex gap-2"><select class="form-select" @change="select"><option value="">All properties</option><option v-for="property in properties" :key="property.id" :value="property.id" :selected="property.id === propertyId">{{ property.name }}</option></select><Link class="btn btn-outline-primary" :href="appUrl(`/vendor/hotel/operations?date=${date}`)">Today</Link><Link class="btn btn-outline-primary" :href="appUrl(`/vendor/hotel/operations?date=${tomorrow}`)">Tomorrow</Link></div></div>
    <div class="row g-3 mb-4"><div v-for="(value, label) in { 'Arrivals': dashboard.kpis.arrivals, 'Departures': dashboard.kpis.departures, 'In-house': dashboard.kpis.in_house, 'Upcoming': dashboard.kpis.upcoming, 'Attention': dashboard.kpis.attention, 'Occupancy': `${dashboard.kpis.occupancy}%` }" :key="label" class="col-6 col-xl-2"><div class="card h-100"><div class="card-body"><div class="small text-muted">{{ label }}</div><div class="fs-3 fw-semibold">{{ value }}</div></div></div></div></div>
    <div v-for="section in [{ title: 'Attention required', rows: dashboard.attention }, { title: 'Arrivals', rows: dashboard.arrivals }, { title: 'Departures', rows: dashboard.departures }, { title: 'In-house', rows: dashboard.in_house }, { title: 'Upcoming bookings', rows: dashboard.upcoming }]" :key="section.title" class="card mb-3"><div class="card-header fw-semibold">{{ section.title }}</div><div v-if="!section.rows.length" class="card-body text-muted">Nothing requiring attention.</div><div v-else class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Booking</th><th>Guest</th><th>Property</th><th>Stay</th><th>Status</th><th>Payment</th><th>Action</th></tr></thead><tbody><tr v-for="row in section.rows" :key="row.id"><td><Link :href="row.url">{{ row.booking_number }}</Link></td><td>{{ row.guest_name }}<span v-if="row.special_requests" class="badge text-bg-warning ms-2">Request</span></td><td>{{ row.property }}</td><td>{{ row.check_in }} → {{ row.check_out }}</td><td>{{ row.status }}</td><td>{{ row.payment_status }}</td><td><div class="d-flex gap-1"><button v-for="(label, status) in row.status_actions" :key="status" class="btn btn-sm btn-outline-primary" @click="changeStatus(row, status)">{{ label }}</button><Link class="btn btn-sm btn-outline-secondary" :href="row.url">View</Link></div></td></tr></tbody></table></div></div>
    <div class="card"><div class="card-header fw-semibold">Room availability summary</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Property</th><th>Room type</th><th>Capacity</th><th>Reserved</th><th>Available</th><th>Control</th></tr></thead><tbody><tr v-for="room in dashboard.rooms" :key="`${room.property}-${room.room_type}`"><td>{{ room.property }}</td><td>{{ room.room_type }}</td><td>{{ room.capacity }}</td><td>{{ room.reserved }}</td><td>{{ room.available }}</td><td><span v-if="room.stop_sell" class="badge text-bg-danger">Stop sell</span><span v-else>Open</span></td></tr><tr v-if="!dashboard.rooms.length"><td colspan="6" class="text-muted">No active room types.</td></tr></tbody></table></div></div>
</div></VendorLayout></template>
